{
  "name": "HTTP规则推送器",
  "name_en": "HTTP Rule Pusher",
  "manufacturer": "",
  "description": "用于通过HTTP向实验室数据处理集群提交规则和帧级任务的软件组件，常见于显微成像等实验数据的自动化处理流程中。",
  "description_en": "A software component for submitting rules and frame-level tasks over HTTP to a laboratory data-processing cluster, commonly used in automated workflows for microscopy and other experimental data analysis.",
  "actions": [
    {
      "action_name": "auto-post_rule",
      "description": "通过HTTP提交处理规则到集群。",
      "description_en": "Submit a processing rule to the cluster over HTTP."
    },
    {
      "action_name": "auto-fileTasksForFrames",
      "description": "为各个数据帧生成并提交任务定义。",
      "description_en": "Generate and submit task definitions for individual data frames."
    },
    {
      "action_name": "auto-cleanup",
      "description": "清理已提交任务相关的临时状态或资源。",
      "description_en": "Clean up temporary state or resources associated with submitted tasks."
    }
  ],
  "tag_hints": [
    "HTTP task submission",
    "cluster data processing",
    "microscopy image analysis",
    "workflow automation",
    "frame-based task generation",
    "PYME"
  ]
}

